const rawText = $input.first()?.json?.output ?? "";

function safeParseJson(text) {
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start === -1 || end === -1 || end <= start) return null;
  const jsonString = text.substring(start, end + 1);
  try { return JSON.parse(jsonString); } catch { return null; }
}

const parsed = safeParseJson(rawText);

if (!parsed) {
  return [{
    json: {
      accion: "INFO",
      lead_tipo: "ADULTO",
      origen: "ORGANICO",
      intencion: "INFO",
      completitud: "BAJA",
      instruccion: "Responder de forma general y pedir 1 dato clave para orientar.",
      mensaje: rawText,
      es_texto: true,
      es_audio: false,
      es_imagen: false,
      es_pdf: false,
      parse_error: true
    }
  }];
}

return [{ json: parsed }];

const crudo = String($('Coordinador Academia').first().json.output || '').trim();
const msg = String($('Parse code').first().json.mensaje || '').trim();

// El agente decidió no responder a un simple acuse ("ok", "gracias"): no se envía nada.
// Salvaguarda: solo se respeta si el mensaje de la persona es corto y no es una pregunta.
if (/^NO_RESPONDER\.?$/i.test(crudo)) {
  if (msg.length <= 30 && !msg.includes('?')) return [];
  return [{ json: { value: '¿Me repetís la consulta así te ayudo mejor?' } }];
}

let out = crudo;

// WhatsApp no interpreta links en markdown: dejar solo la URL
out = out.replace(/\[([^\]]*)\]\((https?:\/\/[^)\s]+)\)/g, '$2');
out = out.replace(/<(https?:\/\/[^>\s]+)>/g, '$1');
// Fla escribe en texto plano: sin **negrita**, sin # títulos y sin viñetas con guion
out = out.replace(/\*\*(.+?)\*\*/g, '$1');
out = out.replace(/^[ \t]*#{1,6}[ \t]*/gm, '');
out = out.replace(/^[ \t]*[-•*][ \t]+/gm, '');

// Frases de relleno que Fla nunca dice: se descartan si ocupan una línea entera.
// Las PREGUNTAS de cierre no se tocan: llevan a la persona al siguiente paso.
const EMO = '[\\p{Extended_Pictographic}\\uFE0F\\s]*';
const GENERICAS = [
  new RegExp('^estoy acá para ayudarte[.!]*' + EMO + '$', 'iu'),
  new RegExp('^cualquier (duda|otra consulta|otra cosa)[^.!]*[.!]*' + EMO + '$', 'iu'),
  new RegExp('^no dudes en[^.!]*[.!]*' + EMO + '$', 'iu')
];

let partes = out.split(/\n\s*\n/).map((s) => s.trim()).filter((s) => s.length > 0);
const limpias = partes
  .map((p) => p.split('\n').filter((l) => !GENERICAS.some((re) => re.test(l.trim()))).join('\n').trim())
  .filter((p) => p.length > 0);
if (limpias.length > 0) partes = limpias;

// Fla casi no usa emojis: máximo uno por respuesta (se respetan los ✨ de las listas)
let usado = false;
partes = partes.map((p) =>
  p.replace(/[\p{Extended_Pictographic}]️?/gu, (m) => {
    if (m.startsWith('✨')) return m;
    if (!usado) { usado = true; return m; }
    return '';
  }).replace(/[ \t]+$/gm, '').trim()
).filter((p) => p.length > 0);

// Meta cobra cada mensaje: se agrupa todo en 1 mensaje si es corto y, como máximo, en 2
const MAX_UN_MENSAJE = 450;
const MAX_MENSAJES = 2;
if (partes.length > 1) {
  const total = partes.join('\n\n');
  if (total.length <= MAX_UN_MENSAJE) {
    partes = [total];
  } else if (partes.length > MAX_MENSAJES) {
    partes = [partes[0], partes.slice(1).join('\n\n')];
  }
  // Un saludo corto no se manda solo (sería un mensaje pagado sin contenido): se pega al siguiente
  if (partes.length === 2 && partes[0].length <= 60) {
    partes = [partes[0] + '\n\n' + partes[1]];
  }
}

if (partes.length === 0) partes.push(out.trim());

return partes.map((item) => ({
  json: { value: item }
}));

const merged = $input.first().json;
let rawText = '';
try {
  rawText = merged.output[0].content[0].text;
} catch (e) {
  rawText = '{}';
}
const driveUrl = merged.webViewLink || null;

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = { es_comprobante: false, descripcion_si_no_es_pago: rawText };
}
parsed.comprobante_url = driveUrl;

return [{ json: { textoFinal: JSON.stringify(parsed) } }];
